'use client'

import { Spinner } from '@astrale-os/ui/spinner'
import { Radar, TriangleAlert } from 'lucide-react'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'

import type { LogEntry, LogLevel, ServiceName, TimeRange } from './types.js'

import { LogList } from './log-list.js'
import { exportLogsAsJson, filterLogs } from './log-utils.js'
import { TopBar } from './top-bar.js'

export interface LogViewerProps {
  defaultLogs?: LogEntry[]
  isLoading?: boolean
  streamError?: string | null
  onNextLiveEntry?(): Promise<LogEntry> | LogEntry
  onCopyLogs?(logs: LogEntry[]): Promise<void> | void
  onExportLogs?(logs: LogEntry[]): Promise<void> | void
}

export function LogViewer({
  defaultLogs = [],
  isLoading = false,
  streamError = null,
  onNextLiveEntry,
  onCopyLogs,
  onExportLogs,
}: LogViewerProps = {}) {
  // Core state
  const [logs, setLogs] = useState<LogEntry[]>(defaultLogs)

  // Filter state
  const [searchQuery, setSearchQuery] = useState('')
  const [activeLevels, setActiveLevels] = useState<Set<LogLevel>>(new Set())
  const [activeServices, setActiveServices] = useState<Set<ServiceName>>(new Set())
  const [timeRange, setTimeRange] = useState<TimeRange>('24h')

  // UI state
  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set())
  const [selectedEntry, setSelectedEntry] = useState<LogEntry | null>(null)
  const [liveTail, setLiveTail] = useState(false)
  const [follow, setFollow] = useState(true)

  // Host action state
  const [pendingMessage, setPendingMessage] = useState<string | null>(null)
  const [status, setStatus] = useState<{ tone: 'success' | 'error'; message: string } | null>(null)

  // Live tail interval ref
  const liveTailRef = useRef<ReturnType<typeof setInterval> | null>(null)

  // Follow tail viewport ref
  const viewport = useRef<HTMLDivElement>(null)

  const runAction = useCallback(
    async (
      busyMessage: string,
      successMessage: string,
      errorMessage: string,
      perform: () => Promise<void> | void,
    ) => {
      setPendingMessage(busyMessage)
      setStatus(null)
      try {
        await perform()
        setStatus({ tone: 'success', message: successMessage })
      } catch {
        setStatus({ tone: 'error', message: errorMessage })
      } finally {
        setPendingMessage(null)
      }
    },
    [],
  )

  const appendLiveEntry = useCallback(async () => {
    if (!onNextLiveEntry) return
    try {
      const newEntry = await onNextLiveEntry()
      setLogs((prev) => [newEntry, ...prev])
    } catch {
      setStatus({ tone: 'error', message: 'Could not append the next log entry.' })
    }
  }, [onNextLiveEntry])

  // Live tail effect
  useEffect(() => {
    if (liveTail) {
      liveTailRef.current = setInterval(() => {
        void appendLiveEntry()
      }, 2500)
    } else {
      if (liveTailRef.current) {
        clearInterval(liveTailRef.current)
        liveTailRef.current = null
      }
    }

    return () => {
      if (liveTailRef.current) {
        clearInterval(liveTailRef.current)
      }
    }
  }, [liveTail, appendLiveEntry])

  // Filtered logs
  const filteredLogs = useMemo(
    () =>
      filterLogs(logs, {
        levels: activeLevels,
        services: activeServices,
        timeRange,
        searchQuery,
      }),
    [logs, activeLevels, activeServices, timeRange, searchQuery],
  )

  // Follow tail effect
  useEffect(() => {
    if (!follow) {
      return
    }
    const rafId = requestAnimationFrame(() => {
      viewport.current?.scrollTo({ top: 0 })
    })

    return () => {
      cancelAnimationFrame(rafId)
    }
  }, [filteredLogs, follow])

  const handleViewportScroll = useCallback((element: HTMLDivElement) => {
    const isAtNewest = element.scrollTop <= 0

    if (isAtNewest) {
      return setFollow(true)
    }
    return setFollow(false)
  }, [])

  // Handlers
  const handleToggleLevel = useCallback((level: LogLevel) => {
    setActiveLevels((prev) => {
      const next = new Set(prev)
      if (next.has(level)) {
        next.delete(level)
      } else {
        next.add(level)
      }
      return next
    })
  }, [])

  const handleServiceChange = useCallback((service: ServiceName | 'all') => {
    if (service === 'all') {
      setActiveServices(new Set())
    } else {
      setActiveServices(new Set([service]))
    }
  }, [])

  const handleToggleExpand = useCallback((id: string) => {
    setExpandedIds((prev) => {
      const next = new Set(prev)
      if (next.has(id)) {
        next.delete(id)
      } else {
        next.add(id)
      }
      return next
    })
  }, [])

  const handleSelect = useCallback((entry: LogEntry) => {
    setSelectedEntry((prev) => (prev?.id === entry.id ? null : entry))
  }, [])

  const handleClearFilters = useCallback(() => {
    setSearchQuery('')
    setActiveLevels(new Set())
    setActiveServices(new Set())
    setTimeRange('24h')
  }, [])

  const getLogsText = useCallback(
    () =>
      filteredLogs
        .map((e) => [e.timestamp.toISOString(), e.level, e.service, e.message].join('\t'))
        .join('\n'),
    [filteredLogs],
  )

  const handleCopy = useCallback(async () => {
    await runAction(
      'Copying logs…',
      `Copied ${filteredLogs.length} log entries to the clipboard.`,
      'Could not copy the visible logs.',
      () => (onCopyLogs ? onCopyLogs(filteredLogs) : navigator.clipboard.writeText(getLogsText())),
    )
  }, [filteredLogs, getLogsText, onCopyLogs, runAction])

  const handleExport = useCallback(async () => {
    await runAction(
      'Exporting logs…',
      `Exported ${filteredLogs.length} log entries.`,
      'Could not export the visible logs.',
      () => {
        if (onExportLogs) return onExportLogs(filteredLogs)
        const json = exportLogsAsJson(filteredLogs)
        const blob = new Blob([json], { type: 'application/json' })
        const url = URL.createObjectURL(blob)
        const a = document.createElement('a')
        a.href = url
        a.download = `logpilot-export-${new Date().toISOString().slice(0, 19)}.json`
        a.click()
        URL.revokeObjectURL(url)
      },
    )
  }, [filteredLogs, onExportLogs, runAction])

  const handleToggleLiveTail = useCallback(() => {
    setLiveTail((prev) => !prev)
  }, [])

  const statusMessage = status === null ? '' : status.message
  const statusToneClass = status?.tone === 'error' ? 'text-red-400' : 'text-zinc-400'

  // Loading state
  if (isLoading) {
    return (
      <div className="flex-1 flex items-center justify-center bg-zinc-950">
        <div className="text-center space-y-3">
          <Radar className="size-8 text-blue-500 animate-spin mx-auto" />
          <div className="text-sm text-zinc-400">Generating log data…</div>
        </div>
      </div>
    )
  }

  return (
    <div className="flex-1 flex flex-col min-h-0 bg-zinc-950 text-zinc-100">
      {/* Top bar */}
      <TopBar
        searchQuery={searchQuery}
        onSearchChange={setSearchQuery}
        activeLevels={activeLevels}
        onToggleLevel={handleToggleLevel}
        activeServices={activeServices}
        onServiceChange={handleServiceChange}
        timeRange={timeRange}
        onTimeRangeChange={setTimeRange}
        liveTail={liveTail}
        onToggleLiveTail={handleToggleLiveTail}
        follow={follow}
        onFollowChange={setFollow}
        isEmpty={filteredLogs.length === 0}
        onClearFilters={handleClearFilters}
        onCopy={() => void handleCopy()}
        onExport={() => void handleExport()}
        totalCount={logs.length}
        filteredCount={filteredLogs.length}
      />

      {/* Stream error */}
      {streamError ? (
        <div className="flex items-center gap-2 px-4 py-2 bg-destructive/20 text-destructive-foreground text-xs border-b border-destructive/40 shrink-0">
          <TriangleAlert className="shrink-0" />
          <span>Stream error: {streamError}</span>
        </div>
      ) : null}

      {/* Host action feedback */}
      <p
        role="status"
        aria-live="polite"
        className={`flex items-center gap-1.5 px-3 py-1 text-xs ${statusToneClass}`}
      >
        {pendingMessage === null ? (
          statusMessage
        ) : (
          <>
            <Spinner aria-hidden className="size-3.5" />
            {pendingMessage}
          </>
        )}
      </p>

      {/* Main content */}
      <div className="flex-1 flex min-h-0">
        {/* Log list */}
        <LogList
          logs={filteredLogs}
          expandedIds={expandedIds}
          selectedEntry={selectedEntry}
          onToggleExpand={handleToggleExpand}
          onSelect={handleSelect}
          viewportRef={viewport}
          onViewportScroll={handleViewportScroll}
        />
      </div>
    </div>
  )
}

'use client'

import { Button } from '@astrale-os/ui/button'
import { cn } from '@astrale-os/ui/class-name'
import { Toggle } from '@astrale-os/ui/toggle'
import { ArrowDownToLine, Copy, Download, Pause, Play, Search, X } from 'lucide-react'
import { useCallback } from 'react'

import type { LogLevel, ServiceName, TimeRange } from './types.js'

import { ALL_LEVELS, ALL_SERVICES, LEVEL_COLORS, TIME_RANGE_LABELS } from './types.js'

interface TopBarProps {
  searchQuery: string
  onSearchChange: (query: string) => void
  activeLevels: Set<LogLevel>
  onToggleLevel: (level: LogLevel) => void
  activeServices: Set<ServiceName>
  onServiceChange: (service: ServiceName | 'all') => void
  timeRange: TimeRange
  onTimeRangeChange: (range: TimeRange) => void
  liveTail: boolean
  onToggleLiveTail: () => void
  follow: boolean
  onFollowChange: (follow: boolean) => void
  isEmpty: boolean
  onClearFilters: () => void
  onCopy: () => void
  onExport: () => void
  totalCount: number
  filteredCount: number
}

export function TopBar({
  searchQuery,
  onSearchChange,
  activeLevels,
  onToggleLevel,
  activeServices,
  onServiceChange,
  timeRange,
  onTimeRangeChange,
  liveTail,
  onToggleLiveTail,
  follow,
  onFollowChange,
  isEmpty,
  onClearFilters,
  onCopy,
  onExport,
  totalCount,
  filteredCount,
}: TopBarProps) {
  const handleServiceSelect = useCallback(
    (e: React.ChangeEvent<HTMLSelectElement>) => {
      onServiceChange(e.target.value as ServiceName | 'all')
    },
    [onServiceChange],
  )

  const handleTimeRangeSelect = useCallback(
    (e: React.ChangeEvent<HTMLSelectElement>) => {
      onTimeRangeChange(e.target.value as TimeRange)
    },
    [onTimeRangeChange],
  )

  const hasActiveFilters =
    activeLevels.size > 0 ||
    activeServices.size > 0 ||
    searchQuery.trim() !== '' ||
    timeRange !== '24h'

  return (
    <div className="border-b border-zinc-800 bg-zinc-950/80 backdrop-blur-sm">
      {/* Row 1: Search + actions */}
      <div className="flex flex-wrap items-center gap-2 px-3 py-2">
        {/* Search */}
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 size-3.5 text-zinc-500" />
          <input
            type="text"
            placeholder="Search logs..."
            value={searchQuery}
            onChange={(e) => onSearchChange(e.target.value)}
            className="w-full h-8 pl-8 pr-8 rounded-lg border border-zinc-700 bg-zinc-900 text-sm text-zinc-300 placeholder:text-zinc-600 outline-none focus:border-blue-500/50 focus:ring-1 focus:ring-blue-500/25 transition-colors font-mono"
          />
          {searchQuery && (
            <button
              type="button"
              onClick={() => onSearchChange('')}
              aria-label="Clear search"
              className="absolute right-2 top-1/2 -translate-y-1/2 text-zinc-500 hover:text-zinc-300"
            >
              <X className="size-3.5" />
            </button>
          )}
        </div>

        {/* Count badge */}
        <span className="text-[11px] text-zinc-500 font-mono shrink-0">
          {filteredCount === totalCount ? (
            <>{totalCount} entries</>
          ) : (
            <>
              {filteredCount}
              <span className="text-zinc-600"> / {totalCount}</span>
            </>
          )}
        </span>

        <div className="h-4 w-px bg-zinc-800" />

        {/* Live tail */}
        <Button
          variant={liveTail ? 'default' : 'outline'}
          size="sm"
          onClick={onToggleLiveTail}
          aria-pressed={liveTail}
          className={cn(liveTail && 'bg-green-600 hover:bg-green-700 text-white border-green-600')}
        >
          {liveTail ? <Pause className="size-3.5 mr-1" /> : <Play className="size-3.5 mr-1" />}
          {liveTail ? 'Tailing' : 'Live Tail'}
        </Button>

        <div className="h-4 w-px bg-zinc-800" />

        {/* Action buttons */}
        <Button variant="ghost" size="icon-sm" onClick={onCopy} aria-label="Copy" title="Copy">
          <Copy className="size-3.5" />
        </Button>
        <Button
          variant="ghost"
          size="icon-sm"
          onClick={onExport}
          aria-label="Export filtered logs"
          title="Export filtered logs"
        >
          <Download className="size-3.5" />
        </Button>

        <div className="h-4 w-px bg-zinc-800" />

        {/* Follow logs */}
        <Toggle
          onPressedChange={onFollowChange}
          pressed={isEmpty ? false : follow}
          disabled={isEmpty}
          variant="outline"
          size="sm"
          aria-label="Toggle follow logs"
          title="Follow logs"
        >
          <ArrowDownToLine className="size-4" />
        </Toggle>
      </div>

      {/* Row 2: Filters */}
      <div className="flex items-center gap-2 px-3 py-1.5 border-t border-zinc-800/50 flex-wrap">
        {/* Level toggles */}
        <span className="text-[10px] uppercase tracking-wider text-zinc-600 mr-1">Level</span>
        <div className="flex items-center gap-1">
          {ALL_LEVELS.map((level) => {
            const colors = LEVEL_COLORS[level]
            const isActive = activeLevels.has(level)
            return (
              <button
                key={level}
                type="button"
                onClick={() => onToggleLevel(level)}
                aria-pressed={isActive}
                className={cn(
                  'px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider transition-all duration-100 border',
                  isActive
                    ? cn(colors.bg, colors.text, 'border-current/20')
                    : 'bg-zinc-900 text-zinc-600 border-zinc-800 hover:text-zinc-400 hover:border-zinc-700',
                )}
              >
                {level}
              </button>
            )
          })}
        </div>

        <div className="h-4 w-px bg-zinc-800 mx-1" />

        {/* Service filter */}
        <span className="text-[10px] uppercase tracking-wider text-zinc-600 mr-1">Service</span>
        <select
          value={activeServices.size === 0 ? 'all' : Array.from(activeServices)[0]}
          onChange={handleServiceSelect}
          aria-label="Service"
          className="h-6 rounded border border-zinc-700 bg-zinc-900 px-2 text-[11px] text-zinc-400 outline-none focus:border-blue-500/50 cursor-pointer"
        >
          <option value="all">All Services</option>
          {ALL_SERVICES.map((s) => (
            <option key={s} value={s}>
              {s}
            </option>
          ))}
        </select>

        <div className="h-4 w-px bg-zinc-800 mx-1" />

        {/* Time range */}
        <span className="text-[10px] uppercase tracking-wider text-zinc-600 mr-1">Time</span>
        <select
          value={timeRange}
          onChange={handleTimeRangeSelect}
          aria-label="Time"
          className="h-6 rounded border border-zinc-700 bg-zinc-900 px-2 text-[11px] text-zinc-400 outline-none focus:border-blue-500/50 cursor-pointer"
        >
          {Object.entries(TIME_RANGE_LABELS).map(([value, label]) => (
            <option key={value} value={value}>
              {label}
            </option>
          ))}
        </select>

        {/* Clear filters */}
        {hasActiveFilters && (
          <>
            <div className="h-4 w-px bg-zinc-800 mx-1" />
            <button
              type="button"
              onClick={onClearFilters}
              className="flex items-center gap-1 text-[10px] text-zinc-500 hover:text-zinc-300 transition-colors"
            >
              <X className="size-3" />
              Clear filters
            </button>
          </>
        )}
      </div>
    </div>
  )
}

'use client'

import { format, isSameDay } from 'date-fns'
import { useMemo } from 'react'

import type { LogEntry } from './types.js'

import { LogEntryRow } from './log-entry-row.js'

interface LogListProps {
  logs: LogEntry[]
  expandedIds: Set<string>
  selectedEntry: LogEntry | null
  onToggleExpand: (id: string) => void
  onSelect: (entry: LogEntry) => void
  viewportRef?: React.Ref<HTMLDivElement>
  onViewportScroll?: (viewport: HTMLDivElement) => void
}

export function LogList({
  logs,
  expandedIds,
  selectedEntry,
  onToggleExpand,
  onSelect,
  viewportRef,
  onViewportScroll,
}: LogListProps) {
  // Group logs by date for sticky separators
  const groupedLogs = useMemo(() => {
    const groups: { date: Date; entries: LogEntry[] }[] = []
    let currentGroup: { date: Date; entries: LogEntry[] } | null = null

    for (const log of logs) {
      if (!currentGroup || !isSameDay(currentGroup.date, log.timestamp)) {
        currentGroup = { date: log.timestamp, entries: [] }
        groups.push(currentGroup)
      }
      currentGroup.entries.push(log)
    }

    return groups
  }, [logs])

  if (logs.length === 0) {
    return (
      <div className="flex-1 flex items-center justify-center text-zinc-500">
        <div className="text-center space-y-2">
          <div className="text-4xl">📋</div>
          <div className="text-sm">No log entries match your filters</div>
          <div className="text-xs text-zinc-600">Try adjusting your search or filter criteria</div>
        </div>
      </div>
    )
  }

  let globalIndex = 0

  return (
    <div
      ref={viewportRef}
      onScroll={(event) => onViewportScroll?.(event.currentTarget)}
      className="flex-1 overflow-y-auto min-h-0"
    >
      {groupedLogs.map((group) => (
        <div key={group.date.toISOString()}>
          {/* Sticky date separator */}
          <div className="sticky top-0 z-10 bg-zinc-900/95 backdrop-blur-sm border-b border-zinc-700/50 px-3 py-1">
            <span className="text-[10px] uppercase tracking-widest text-zinc-500 font-medium">
              {format(group.date, 'EEEE, MMMM d, yyyy')}
            </span>
            <span className="text-[10px] text-zinc-600 ml-2">({group.entries.length} entries)</span>
          </div>

          {/* Log entries */}
          {group.entries.map((entry) => {
            const idx = globalIndex++
            return (
              <LogEntryRow
                key={entry.id}
                entry={entry}
                index={idx}
                isExpanded={expandedIds.has(entry.id)}
                isSelected={selectedEntry?.id === entry.id}
                onToggleExpand={onToggleExpand}
                onSelect={onSelect}
              />
            )
          })}
        </div>
      ))}
    </div>
  )
}

'use client'

import { cn } from '@astrale-os/ui/class-name'
import { format } from 'date-fns'
import { ChevronDown, ChevronRight } from 'lucide-react'
import { memo, useCallback } from 'react'

import type { LogEntry } from './types.js'

import { LEVEL_COLORS, SERVICE_COLORS } from './types.js'

interface LogEntryRowProps {
  entry: LogEntry
  index: number
  isExpanded: boolean
  isSelected: boolean
  onToggleExpand: (id: string) => void
  onSelect: (entry: LogEntry) => void
}

export const LogEntryRow = memo(function LogEntryRow({
  entry,
  index,
  isExpanded,
  isSelected,
  onToggleExpand,
  onSelect,
}: LogEntryRowProps) {
  const levelColor = LEVEL_COLORS[entry.level]
  const serviceColor = SERVICE_COLORS[entry.service]

  const handleClick = useCallback(() => {
    onSelect(entry)
    onToggleExpand(entry.id)
  }, [entry, onSelect, onToggleExpand])

  return (
    <div
      className={cn(
        'border-b border-zinc-800/50 transition-colors duration-100',
        index % 2 === 0 ? 'bg-zinc-950/50' : 'bg-zinc-900/30',
        isSelected && '!bg-blue-500/10 border-l-2 border-l-blue-500',
        !isSelected && 'border-l-2 border-l-transparent',
        'hover:bg-zinc-800/40 cursor-pointer',
      )}
    >
      {/* Collapsed row */}
      <button
        type="button"
        onClick={handleClick}
        aria-expanded={isExpanded}
        className="w-full flex items-center gap-2 px-3 py-1.5 text-left"
      >
        <span className="shrink-0 text-zinc-600">
          {isExpanded ? (
            <ChevronDown className="size-3.5" />
          ) : (
            <ChevronRight className="size-3.5" />
          )}
        </span>

        <span className="font-mono text-[11px] text-zinc-500 shrink-0 w-[85px]">
          {format(entry.timestamp, 'HH:mm:ss.SSS')}
        </span>

        <span
          className={cn(
            'shrink-0 px-1.5 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider w-[52px] text-center',
            levelColor.bg,
            levelColor.text,
          )}
        >
          {entry.level}
        </span>

        <span
          className={cn(
            'shrink-0 px-1.5 py-0.5 rounded text-[10px] font-medium w-[72px] text-center',
            serviceColor.bg,
            serviceColor.text,
          )}
        >
          {entry.service}
        </span>

        <span className="font-mono text-[12px] text-zinc-300 truncate min-w-0">
          {entry.message}
        </span>

        {entry.payload && (
          <span className="shrink-0 text-[10px] text-zinc-600 font-mono">{'{…}'}</span>
        )}
        {entry.stackTrace && (
          <span className="shrink-0 text-[10px] text-red-500/60 font-mono">⚠ stack</span>
        )}
      </button>

      {/* Expanded detail */}
      {isExpanded && (
        <div className="px-10 pb-3 space-y-3 animate-in fade-in slide-in-from-top-1 duration-200">
          {/* Full message */}
          <div>
            <div className="text-[10px] uppercase tracking-wider text-zinc-600 mb-1">Message</div>
            <div className="font-mono text-xs text-zinc-300 bg-zinc-900/80 rounded p-2 whitespace-pre-wrap break-all">
              {entry.message}
            </div>
          </div>

          {/* Stack trace */}
          {entry.stackTrace && (
            <div>
              <div className="text-[10px] uppercase tracking-wider text-zinc-600 mb-1">
                Stack Trace
              </div>
              <pre className="font-mono text-[11px] text-red-400/80 bg-red-950/20 rounded p-2 overflow-x-auto whitespace-pre">
                {entry.stackTrace}
              </pre>
            </div>
          )}

          <div className="flex gap-4 text-[10px] text-zinc-600">
            <span>
              ID: <span className="text-zinc-400 font-mono">{entry.id}</span>
            </span>
            <span>
              Full timestamp:{' '}
              <span className="text-zinc-400 font-mono">
                {format(entry.timestamp, 'yyyy-MM-dd HH:mm:ss.SSS')}
              </span>
            </span>
          </div>
        </div>
      )}
    </div>
  )
})

import { isAfter, subDays, subHours } from 'date-fns'

import type { LogEntry, LogLevel, ServiceName, TimeRange } from './types.js'

export function filterLogs(
  logs: LogEntry[],
  opts: {
    levels: Set<LogLevel>
    services: Set<ServiceName>
    timeRange: TimeRange
    searchQuery: string
  },
): LogEntry[] {
  const now = new Date()
  const cutoff = getTimeRangeCutoff(now, opts.timeRange)
  const query = opts.searchQuery.toLowerCase().trim()

  return logs.filter((entry) => {
    if (opts.levels.size > 0 && !opts.levels.has(entry.level)) return false
    if (opts.services.size > 0 && !opts.services.has(entry.service)) return false
    if (!isAfter(entry.timestamp, cutoff)) return false
    if (query && !matchesSearch(entry, query)) return false
    return true
  })
}

function getTimeRangeCutoff(now: Date, range: TimeRange): Date {
  switch (range) {
    case '1h':
      return subHours(now, 1)
    case '6h':
      return subHours(now, 6)
    case '24h':
      return subHours(now, 24)
    case '7d':
      return subDays(now, 7)
  }
}

function matchesSearch(entry: LogEntry, query: string): boolean {
  if (entry.message.toLowerCase().includes(query)) return true
  if (entry.service.toLowerCase().includes(query)) return true
  if (entry.level.toLowerCase().includes(query)) return true
  if (entry.payload && JSON.stringify(entry.payload).toLowerCase().includes(query)) return true
  if (entry.stackTrace?.toLowerCase().includes(query)) return true
  return false
}

export function parseRawLogs(raw: string): LogEntry[] {
  const lines = raw.split('\n').filter((l) => l.trim())
  const entries: LogEntry[] = []

  for (const line of lines) {
    const entry = tryParseJsonLog(line) ?? tryParseTextLog(line)
    if (entry) entries.push(entry)
  }

  return entries
}

function tryParseJsonLog(line: string): LogEntry | null {
  try {
    const obj = JSON.parse(line) as Record<string, unknown>
    if (!obj.message && !obj.msg) return null

    return {
      id: `imported-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      timestamp: obj.timestamp ? new Date(obj.timestamp as string) : new Date(),
      level: normalizeLevel(String(obj.level ?? obj.severity ?? 'INFO')),
      service: normalizeService(String(obj.service ?? obj.source ?? 'API')),
      message: String(obj.message ?? obj.msg),
      payload: obj.data ? (obj.data as Record<string, unknown>) : undefined,
      stackTrace: obj.stack ? String(obj.stack) : undefined,
    }
  } catch {
    return null
  }
}

function tryParseTextLog(line: string): LogEntry | null {
  // Common format: [2025-01-01 12:00:00] [ERROR] [API] Some message
  const match = line.match(
    /\[?([\d\-T:.Z+ ]+)\]?\s*\[?(DEBUG|INFO|WARN|WARNING|ERROR|FATAL|CRITICAL)\]?\s*\[?(\w+)\]?\s*[-:]?\s*(.+)/i,
  )

  if (match) {
    return {
      id: `imported-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      timestamp: new Date(match[1]),
      level: normalizeLevel(match[2]),
      service: normalizeService(match[3]),
      message: match[4].trim(),
    }
  }

  // Fallback: treat entire line as message
  return {
    id: `imported-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    timestamp: new Date(),
    level: 'INFO',
    service: 'API',
    message: line.trim(),
  }
}

function normalizeLevel(raw: string): LogLevel {
  const upper = raw.toUpperCase()
  if (upper === 'WARNING' || upper === 'WARN') return 'WARN'
  if (upper === 'CRITICAL' || upper === 'FATAL') return 'FATAL'
  if (['DEBUG', 'INFO', 'ERROR'].includes(upper)) return upper as LogLevel
  return 'INFO'
}

function normalizeService(raw: string): ServiceName {
  const valid: ServiceName[] = ['API', 'Auth', 'Worker', 'Scheduler', 'Gateway']
  const found = valid.find((s) => s.toLowerCase() === raw.toLowerCase())
  return found ?? 'API'
}

export function buildHeatmapData(
  logs: LogEntry[],
): { hour: number; label: string; counts: Record<LogLevel, number> }[] {
  const now = new Date()
  const data: { hour: number; label: string; counts: Record<LogLevel, number> }[] = []

  for (let i = 23; i >= 0; i--) {
    const hourStart = new Date(now)
    hourStart.setHours(now.getHours() - i, 0, 0, 0)
    const hourEnd = new Date(hourStart)
    hourEnd.setHours(hourStart.getHours() + 1)

    const hourLabel = `${hourStart.getHours().toString().padStart(2, '0')}:00`
    const counts: Record<LogLevel, number> = {
      DEBUG: 0,
      INFO: 0,
      WARN: 0,
      ERROR: 0,
      FATAL: 0,
    }

    for (const entry of logs) {
      if (entry.timestamp >= hourStart && entry.timestamp < hourEnd) {
        counts[entry.level]++
      }
    }

    data.push({ hour: i, label: hourLabel, counts })
  }

  return data
}

export function exportLogsAsJson(logs: LogEntry[]): string {
  const serializable = logs.map((l) => ({
    id: l.id,
    timestamp: l.timestamp.toISOString(),
    level: l.level,
    service: l.service,
    message: l.message,
    ...(l.payload && { payload: l.payload }),
    ...(l.stackTrace && { stackTrace: l.stackTrace }),
  }))
  return JSON.stringify(serializable, null, 2)
}
